    [13310531] = {
        id = 13310531,
        text = "Cher Partenaires, \n En ce début d'été, nous allons lancer une mise à jour majeure avec de nombreuses et splendides nouvelles fonctionnalités !\n Nous avons préparé de nombreux nouveaux modes de jeu et contenus, notamment Porte Sharam, Lutte de Territoire et Défi Pierre Runique. Nous vous souhaitons sincèrement de profiter de cette mise à jour. \n Nous apprécions vraiment votre soutien et votre tolérance !\n Les rencontres ne s'arrêtent jamais ! Je vous aime tous !\n - Designer Sima",
        minipack = 0,
    },
    [13310539] = {
        id = 13310539,
        text = "Chers Partenaires, \n Une autre idole charismatique sera bientôt disponible ! De plus, la voix off de votre waifu Mayuri est disponible dès maintenant ! Que dirait Mayuri ?\n En raison de l'emploi du temps des actrices, la nouvelle voix off n'a pas été ajoutée comme prévu. Pourtant, nous l'avons fait en fin de compte !\n Hot Games continuera à améliorer ce jeu et à vous offrir un meilleur contenu. Les nouveaux contenus peuvent être en retard, mais ils ne seront jamais absents. \n Hot Games",
        minipack = 0,
    },
    [13310547] = {
        id = 13310547,
        text = "Plein de souvenirs.",
        minipack = 0,
    },
    [13310555] = {
        id = 13310555,
        text = "Viens avec moi ! Loue-moi comme vous le souhaitez ! Hé ! Qu'est-ce que c'est exactement... cette étrange demande ?!",
        minipack = 0,
    },
    [13310563] = {
        id = 13310563,
        text = "En décorant le sapin de Noël avec Kotori et Tohka, j'ai reçu un cadeau inattendu.",
