    [910112] = {
        id = 910112,
        text = "On m'a tiré dessus. Mais j'ai quand même été libéré pour voir que Tohka et Origami pouvaient arranger les choses.",
        minipack = 0,
    },
    [910113] = {
        id = 910113,
        text = "Tohka et Origami se battaient pour l'épingle à cheveux en forme de lapin. Apparemment, ce n'était pas des filles ordinaires après tout.",
        minipack = 0,
    },
    [63028] = {
        id = 63028,
        text = "Vous voulez voir votre Esprit bien-aimé dans les plus beaux habits de la page d'accueil ?\n\n1. Dans la page Fille préférée, vous pouvez mettre des vêtements sur vos Esprits et sélectionner la meilleure fille qui sera affichée sur votre page d'accueil. \n\n2. Dans la liste des avatars de Fille préférée sur la gauche, sélectionnez les avatars des Esprits débloqués et Appuyer sur \"Changer\" sur la droite pour changer de Fille préférée. \n\n3. Vous pouvez appuyer sur les onglets \"Changer\", \"Info\" et \"Pose\" pour prévisualiser les effets avant d'effectuer le changement. \n\n4. Étiquette \"Changer\" : Faites glisser les cartes de costume ici pour vérifier à quoi ressemble un Esprit dans tous les costumes. \n\n5. Étiquette \"Info\" : Vérifiez ici les informations de base et l'historique de chaque Esprit, peut-être même des trucs privés !\n\n6. Étiquette \"Pose\" : Vous pouvez vérifier comment les Esprits réagissent lorsque vous les touchez. Si la Faveur n'est pas assez élevé, vous ne pouvez voir que quelques lignes~\n\n7. De plus, tous les contenus \"verrouillés\" de l'interface peuvent être visualisés, ce qui vous permet de vous \"orienter à l'avance\"\n-------------------------------------------\n\nLe Diaporama est disponible !\n\nVous pouvez maintenant faire jouer plusieurs Esprits dans différents costumes (uniquement les plus avancés) en tant que Fille préférée. Lorsque Diaporama est activé, Fille préférée s'affiche sur la page d'accueil à un intervalle déterminé.",
        minipack = 0,
    },
    [910114] = {
        id = 910114,
        text = "Le traitement spécial de Tohka a presque fait jaillir mon sang. Je pense qu'il est temps d'éduquer Yoshino aussi.",
        minipack = 0,
    },
    [910115] = {
        id = 910115,
        text = "Je crois que Origami n'a pas fait d'erreur intentionnelle. J'espérais donc sincèrement que Kusakabe senpai pourrait l'épargner.",
        minipack = 0,
    },
    [910116] = {
        id = 910116,
        text = "Dans la ruelle étroite, nous n'avons pas d'autre choix que d'affronter Origami. La bataille peut éclater à tout moment.",
        minipack = 0,
    },
    [910117] = {
        id = 910117,
        text = "Quand j'ai cru que nous avions perdu Origami, j'ai vu la pointe rouge de sniper sur la poitrine de Tohka.",
