    [1500001] = {
        id = 1500001,
        text = "Annonce",
        minipack = 0,
    },
    [1500002] = {
        id = 1500002,
        text = "Chers joueurs, \n\nTohka Yatogami : [Bonjour tout le monde, nous nous rencontrons enfin !]\nKurumi Tokisaki : [Ara ara~ Salut ! Nous nous rencontrons enfin. Merci pour votre anticipation à long terme, c'est un plaisir de vous rencontrer.] \nOrigami Tobiichi : [Après avoir obtenu la licence de Kadokawa Shoten. L'équipe de développement a travaillé dur pour donner aux fans un jeu bien fait qui satisfera nos fans de DAL.] \nTohka Yatogami : [Umu~ C'est le premier beta test public pour tous les joueurs. Il y a beaucoup de problèmes à régler. Désolé pour le désagrément~ (pleurs dans la salle de bains T-T). Lors des précieux tests, nous avons reçu de nombreuses suggestions et réactions. Ils sont tous bien lus et triés. En outre... nous avons prévu d'ajuster le jeu. Les changements seront implémentés à notre prochain rendez-vous] \nKotori Itsuka : [Nous croyons savoir que beaucoup ont envoyé des commentaires concernant BGM, images d'Esprit, batailles et jeux. Ratatoskr travaille dur pour améliorer ces aspects. Soyez rassurés.] \nTohka Yatogami : [Elle sera interprétée par la voix de l'actrice originale !]\nOrigami Tobiichi : [Elle sera interprétée par la voix de l'actrice originale !]\nKotori Itsuka : [Elle sera interprétée par la voix de l'actrice originale !]\nKurumi Tokisaki : [Si vous avez des questions ou des demandes, rejoignez notre groupe pour ce test : 542524583. Nous avons besoin de votre aide pour améliorer le jeu et notre équipe] \nOrigami Tobiichi : [Merci encore pour votre soutien. Vous êtes notre plus grande motivation pour aller de l'avant] \nTohka Yatogami : [Maintenant, que notre rendez-vous (bataille) commence !] \n\nP.S : Des tonnes d'avantages seront données dans ce test. Veillez à vous connecter tous les jours~\n\nSi vous rencontrez un problème, contactez le service d'assistance aux clients QQ : 4000585151",
        minipack = 0,
    },
    [1500003] = {
        id = 1500003,
        text = "Merci d'avoir participé au bêta-test rapproché de Date A live (emmmm... bien qu'il y ait de nombreux bugs sur lesquels nous devons travailler). \nEn jouant au jeu, n'oubliez pas de faire cette enquête ! Tout ce que vous voulez dire, vous plaindre ou dire ce que vous avez sur le cœur sera envoyé au QG ! Nous apprécions votre choix et nous lirons attentivement chaque réponse.",
        minipack = 0,
    },
