        text = "Où est la chose que tu veux me donner ? Remets-le.",
        minipack = 0,
    },
    [1701446] = {
        id = 1701446,
        text = "Oh, c'est délicieux... toi... c'est quoi ce regard ? Tu as dit que tu voulais que je le mange quoi qu'il arrive, c'est pour ça que j'ai mangé ça !",
