    },
    [1701505] = {
        id = 1701505,
        text = "Kuku, très bien, je vais discuter avec toi pendant un moment. Tu te sentiras honoré. (Note : Ancien, ton chunibyo)",
        minipack = 0,
    },
    [1701506] = {
