    },
    [1701516] = {
        id = 1701516,
        text = "Compris. Je t'invite à nouveau.",
        minipack = 0,
    },
    [1701517] = {
        id = 1701517,
        text = "D'accord. Je me demande quel genre de vêtements tu vas choisir pour Yuzuru.",
        minipack = 0,
    },
    [1701518] = {
