    },
    [1701520] = {
        id = 1701520,
        text = "Carieuse. Que veux-tu faire à Yuzuru dans ce genre d'endroit ?",
        minipack = 0,
    },
    [1701521] = {
        id = 1701521,
        text = "Attente. Entrée en mode de batterie faible.",
        minipack = 0,
    },
    [1701522] = {
        id = 1701522,
        text = "Louange. Il est difficile de trouver ce genre de nourriture délicieuse, même au paradis.",
        minipack = 0,
    },
    [1701523] = {
        id = 1701523,
        text = "Acceptable. Puisque c'est de toi, je ne me retiendrai pas.",
        minipack = 0,
    },
    [1701524] = {
