    },
    [1701537] = {
        id = 1701537,
        text = "C'est donc à cela que ressemble un rendez-vous ? Cela semble intéressant.",
        minipack = 0,
    },
    [1701538] = {
        id = 1701538,
        text = "Ennuyeux - ennuyeux - ne me demandez pas de recommencer.",
        minipack = 0,
    },
    [1701539] = {
        id = 1701539,
        text = "N'oublie pas d'arriver à temps, c'est un ordre.",
        minipack = 0,
    },
    [1701540] = {
        id = 1701540,
        text = "Comment oses-tu me rejeter ? (Menace)",
        minipack = 0,
    },
    [1701541] = {
        id = 1701541,
        text = "Une nouvelle armure de combat ?",
        minipack = 0,
    },
    [1701542] = {
        id = 1701542,
        text = "Comme c'est gênant... pourquoi je dois mettre ce genre de vêtements",
        minipack = 0,
    },
    [1701543] = {
        id = 1701543,
        text = "Comme on peut s'y attendre, les vêtements ordinaires ne sont pas aussi amusants que les armures.",
        minipack = 0,
    },
    [1701544] = {
        id = 1701544,
        text = "Y a-t-il de nouvelles armes ?",
        minipack = 0,
    },
    [1701545] = {
        id = 1701545,
        text = "Montre-moi ce que vous as dans le ventre.",
        minipack = 0,
    },
    [1701546] = {
        id = 1701546,
        text = "Huhh. Eh bien, pas mal. Merci pour vos efforts. Quitter.",
        minipack = 0,
    },
    [1701547] = {
        id = 1701547,
        text = "Ce n'est pas mal, mais peut-être qu'un peu de créativité serait bien.",
        minipack = 0,
    },
    [1701548] = {
        id = 1701548,
        text = "Huhh... ? Il a l'air différent. Je peux l'accepter. Mais ne le prenez pas mal.",
        minipack = 0,
    },
    [1701549] = {
        id = 1701549,
        text = "Qu'est-ce que c'est ? Si tu veux me faire plaisir, fais quelques recherches.",
        minipack = 0,
    },
    [1701550] = {
        id = 1701550,
        text = "Bien, bien, bien... Se faire complimenter par quelqu'un comme vous ne me rendra pas heureux",
        minipack = 0,
    },
    [1701551] = {
        id = 1701551,
        text = "Je suis le plus fort des magiciens !",
        minipack = 0,
    },
    [1701552] = {
        id = 1701552,
        text = "Juste à temps pour vérifier mes nouveaux équipements.",
        minipack = 0,
    },
    [1701553] = {
        id = 1701553,
        text = "Quoi de neuf ? Si ce n'est rien, peux-tu me laisser tranquille ?",
        minipack = 0,
    },
    [1701554] = {
        id = 1701554,
        text = "Il suffit de s'en remettre au personnage le plus puissant : moi.",
        minipack = 0,
    },
    [1701555] = {
        id = 1701555,
        text = "Parce que je suis le plus fort.",
        minipack = 0,
    },
    [1701556] = {
        id = 1701556,
        text = "Ouais ! C'est moi au sommet de ma forme !",
        minipack = 0,
    },
    [1701557] = {
        id = 1701557,
        text = "Voyons qui saura se dresser devant moi !",
        minipack = 0,
    },
    [1701558] = {
        id = 1701558,
        text = "Emhehe, où m'emmènes-tu ?",
        minipack = 0,
    },
    [1701559] = {
        id = 1701559,
        text = "Mon amour est la meilleure~ Je suis super heureuse aujourd'hui.",
        minipack = 0,
    },
    [1701560] = {
        id = 1701560,
        text = "J'aime mon amour le plus~",
        minipack = 0,
    },
    [1701561] = {
        id = 1701561,
        text = "Tu vas apprendre à être patient, mon amour.",
        minipack = 0,
    },
    [1701562] = {
        id = 1701562,
        text = "La \"fête\" d'aujourd'hui s'est bien déroulée.",
        minipack = 0,
    },
    [1701563] = {
        id = 1701563,
        text = "Besoin d'un rappel téléphonique ? Mon amour, ne sois pas en retard.",
        minipack = 0,
    },
    [1701564] = {
        id = 1701564,
        text = "Pourquoi ? Tu ne veux pas m'entendre chanter ? (lésé, pleurant)",
        minipack = 0,
    },
    [1701565] = {
        id = 1701565,
        text = "Veux-tu me voir dans le nouveau costume ?",
        minipack = 0,
    },
    [1701566] = {
        id = 1701566,
        text = "Bonne réaction ! Je t'hypnotise ?",
        minipack = 0,
    },
    [1701567] = {
        id = 1701567,
        text = "Mon amour, regarde, comment tu trouves ce costume ?",
        minipack = 0,
    },
    [1701568] = {
        id = 1701568,
        text = "Mon amour, tu as un cadeau pour moi ? Je suis si heureuse !",
        minipack = 0,
    },
    [1701569] = {
        id = 1701569,
        text = "Mon amour, tu as un cadeau pour moi ? J'attends cela avec impatience.",
        minipack = 0,
    },
    [1701570] = {
        id = 1701570,
        text = "Hum ! C'est si savoureux ! Je peux y sentir l'affection de mon amour.",
        minipack = 0,
    },
    [1701571] = {
        id = 1701571,
        text = "Ara~ Ça a l'air savoureux. Puis-je l'accepter ?",
        minipack = 0,
    },
    [1701572] = {
        id = 1701572,
        text = "Wow~ ! Merci~ ! Pour rendre ce cadeau, je peux te faire un câlin~ !",
        minipack = 0,
    },
    [1701573] = {
        id = 1701573,
        text = "Merci, je le chérirai~ !",
        minipack = 0,
    },
    [1701574] = {
        id = 1701574,
        text = "Mon amour, je t'aime tellement !",
        minipack = 0,
    },
    [1701575] = {
        id = 1701575,
        text = "Lalala, mon amour, tu veux m'entendre chanter ?",
        minipack = 0,
    },
    [1701576] = {
        id = 1701576,
        text = "Je suis sérieux. Comment osent-ils perturber notre rendez-vous ! Comme c'est ennuyeux, humph~",
        minipack = 0,
    },
    [1701577] = {
        id = 1701577,
        text = "Tu n'auras pas mon autographe en me regardant comme ça.",
        minipack = 0,
    },
    [1701578] = {
        id = 1701578,
        text = "Salut~ merci de m'avoir demandé, mon amour. Je suis votre Miku !",
        minipack = 0,
    },
    [1701579] = {
        id = 1701579,
        text = "Je peux chanter encore mieux maintenant !",
        minipack = 0,
    },
    [1701580] = {
        id = 1701580,
        text = "La bataille n'est pas pour les dames, mais pour mon amour, je peux tout faire.",
        minipack = 0,
    },
    [1701581] = {
        id = 1701581,
        text = "Mon amour, laisse-moi te protéger !",
        minipack = 0,
    },
    [1701582] = {
        id = 1701582,
        text = "C'est comme si j'étais dans un rêve. Comme tout le monde, je peux sortir avec toi maintenant.",
        minipack = 0,
    },
    [1701583] = {
        id = 1701583,
        text = "Hehe, je n'aurais jamais pensé être aussi heureux.",
        minipack = 0,
    },
    [1701584] = {
        id = 1701584,
        text = "Ara, tu m'as attrapé, hehe.",
        minipack = 0,
    },
    [1701585] = {
        id = 1701585,
        text = "Peu importe le nombre de fois où je suis venu, j'apprécie toujours cet endroit.",
        minipack = 0,
    },
    [1701586] = {
        id = 1701586,
        text = "Pas de précipitation, prends ton temps.",
        minipack = 0,
    },
    [1701587] = {
        id = 1701587,
        text = "A plus tard alors, j'attends avec impatience.",
        minipack = 0,
    },
    [1701588] = {
        id = 1701588,
        text = "C'est rien. Travaillons dur la prochaine fois.",
        minipack = 0,
    },
    [1701589] = {
        id = 1701589,
        text = "Magasin de vêtements ? Il y a là beaucoup de souvenirs amusants, héhé.",
        minipack = 0,
    },
    [1701590] = {
        id = 1701590,
        text = "Est-ce qu'il convient ?... héhé, je suis content que ça te plaise",
        minipack = 0,
    },
    [1701591] = {
        id = 1701591,
        text = "Cette robe est si jolie. Tu me préfères maintenant ?",
        minipack = 0,
    },
    [1701592] = {
        id = 1701592,
        text = "Hum ? Tu es entré en douce pour me trouver ? Héhé~",
        minipack = 0,
    },
    [1701593] = {
        id = 1701593,
        text = "Tu veux me faire un cadeau ?",
        minipack = 0,
    },
    [1701594] = {
        id = 1701594,
        text = "Cette saveur... Je n'y ai jamais goûté",
        minipack = 0,
    },
    [1701595] = {
        id = 1701595,
        text = "Merci, c'est vraiment délicieux.",
        minipack = 0,
    },
    [1701596] = {
        id = 1701596,
        text = "Je suis si heureuse que tu saches toujours ce que j'aime.",
        minipack = 0,
    },
    [1701597] = {
        id = 1701597,
        text = "Vraiment ! Est-ce vraiment pour moi ?",
        minipack = 0,
    },
    [1701598] = {
        id = 1701598,
        text = "Comme toujours, je t'aime tendrement... je plaisante",
        minipack = 0,
    },
    [1701599] = {
        id = 1701599,
        text = "Je te manque ? C'est bon, je serai là.",
        minipack = 0,
    },
    [1701600] = {
        id = 1701600,
        text = "Je peux sentir, la force de chacun.",
        minipack = 0,
    },
    [1701601] = {
        id = 1701601,
        text = "?Quoi de neuf ?",
        minipack = 0,
    },
    [1701602] = {
        id = 1701602,
        text = "Je suis l'arbitre. Je le ferai - voir à travers toi.",
        minipack = 0,
    },
    [1701603] = {
        id = 1701603,
        text = "Alors... Je peux te protéger.",
        minipack = 0,
    },
    [1701604] = {
        id = 1701604,
        text = "Par rapport aux autres, je ne suis pas assez bon.",
        minipack = 0,
    },
    [1701605] = {
        id = 1701605,
        text = "Pour celui que j'aime, je ferai de mon mieux.",
        minipack = 0,
    },
