    [1701990] = {
        id = 1701990,
        text = "[Événement] Célébration fête du printemps",
        minipack = 0,
    },
    [1701991] = {
        id = 1701991,
        text = "Ha, un rendez-vous... ? Avec moi ? Sérieusement ?",
        minipack = 0,
    },
    [1701992] = {
        id = 1701992,
        text = "Que ferions-nous aujourd'hui ?",
        minipack = 0,
    },
    [1701993] = {
        id = 1701993,
        text = "Tu es une sorte de dur à cuire...",
        minipack = 0,
    },
    [1701994] = {
        id = 1701994,
        text = "Un rendez-vous... ça a l'air amusant... non, rien.",
        minipack = 0,
    },
    [1701995] = {
        id = 1701995,
        text = "Qu'as-tu dis...",
        minipack = 0,
    },
    [1701996] = {
        id = 1701996,
        text = "Si tu veux refuser, dis-le maintenant. Est-ce vraiment autorisé ?",
        minipack = 0,
    },
    [1701997] = {
        id = 1701997,
        text = "Ah, très bien, je pense que oui. Je ne suis pas du tout en colère. Ce n'est que normal.",
        minipack = 0,
    },
    [1701998] = {
        id = 1701998,
        text = "Je veux dire qu'il n'y a rien qui vaille la peine d'être regardé.",
        minipack = 0,
    },
    [1701999] = {
        id = 1701999,
        text = "Alors ne me donne plus de vêtements...",
        minipack = 0,
    },
    [1702000] = {
        id = 1702000,
        text = "Merci... est-ce que je suis... jolie ?",
        minipack = 0,
    },
    [1702001] = {
        id = 1702001,
        text = "Qu'est-ce que c'est ? Oh ? Un cadeau pour moi ?",
        minipack = 0,
    },
    [1702002] = {
        id = 1702002,
        text = "Si tu veux arrêter, fais-le. Il vaut mieux le donner à d'autres filles...",
        minipack = 0,
    },
    [1702003] = {
        id = 1702003,
        text = "Wow, si savoureux, qu'est-ce que c'est ?... Merci....merci.",
        minipack = 0,
    },
    [1702004] = {
        id = 1702004,
        text = "Bof bof.",
        minipack = 0,
    },
    [1702005] = {
        id = 1702005,
        text = "Wow, incroyable...",
        minipack = 0,
    },
    [1702006] = {
        id = 1702006,
        text = "Humph, eh bien, pas mal.",
        minipack = 0,
    },
    [1702007] = {
        id = 1702007,
        text = "... Non, c'est pas mal, non ?",
        minipack = 0,
    },
    [1702008] = {
        id = 1702008,
        text = "Ai-je vraiment le droit de faire cela ?",
        minipack = 0,
    },
    [1702009] = {
        id = 1702009,
        text = "Quoi ?! Un jeu intéressant est sur le point de commencer ?",
        minipack = 0,
    },
    [1702010] = {
        id = 1702010,
        text = "Qu'est-ce que c'est ? Arrête de faire des ourlets et des haussements de tête.",
        minipack = 0,
    },
    [1702011] = {
        id = 1702011,
        text = "Je vais te gâcher la vie !",
        minipack = 0,
    },
    [1702012] = {
        id = 1702012,
        text = "Si elle n'est pas beaucoup améliorée, ne me blâme pas.",
        minipack = 0,
    },
    [1702013] = {
        id = 1702013,
        text = "Compte sur... moi",
        minipack = 0,
    },
    [1702014] = {
        id = 1702014,
        text = "Je suis le seul à pouvoir le faire !",
        minipack = 0,
    },
    [1702015] = {
        id = 1702015,
        text = "Posséder votre Fille préférée - Natsumi",
        minipack = 0,
    },
    [1702016] = {
        id = 1702016,
        text = "Terminez n'importe quelle rendez-vous quotidien avec Natsumi",
        minipack = 0,
    },
    [1702017] = {
        id = 1702017,
        text = "Obtenez une fin cachée avec un rendez-vous quotidien avec Natsumi",
        minipack = 0,
    },
    [1702018] = {
        id = 1702018,
        text = "Obtenez une fin heureuse avec un rendez-vous quotidien avec Natsumi",
