    [1702053] = {
        id = 1702053,
        text = "[Principal] Natsumi_Chapitre 1",
        minipack = 0,
    },
    [1702054] = {
        id = 1702054,
        text = "La jeune fille aux cheveux noirs comme la nuit, a des yeux aussi brillants que les étoiles dans le ciel.",
        minipack = 0,
    },
    [1702055] = {
        id = 1702055,
        text = "Même l'identité de guerrière forte ne peut pas cacher son cœur de fille.",
        minipack = 0,
    },
    [1702056] = {
        id = 1702056,
        text = "Avec un cœur aussi fragile que le verre, elle a peur des étrangers et a besoin de votre attention.",
        minipack = 0,
    },
    [1702057] = {
        id = 1702057,
        text = "Une force puissante et cruelle, avec une beauté encore plus mortelle.",
        minipack = 0,
    },
    [1702058] = {
        id = 1702058,
        text = "Elle essaie de rester calme tout le temps. Cependant, elle se perd toujours dans la chaleur de son frère.",
        minipack = 0,
    },
    [1702059] = {
        id = 1702059,
        text = "[Amour] est la seule raison de son existence. Elle reste au sommet comme un ange.",
        minipack = 0,
    },
    [1702060] = {
        id = 1702060,
        text = "Ne se révèle qu'à ceux en qui elle a confiance.",
        minipack = 0,
    },
    [1702061] = {
        id = 1702061,
        text = "Saint Valentin ? Umu... Tant que je pourrai sortir avec toi, j'appellerai cela une bonne journée. \nÊtre avec moi te rend aussi heureux, n'est-ce pas ?",
        minipack = 0,
    },
    [1702062] = {
        id = 1702062,
        text = "Cher amant, j'espère que vous accepterez ma fleur et ma lettre d'amour. \nViens, passe la belle nuit avec moi !",
        minipack = 0,
    },
    [1702063] = {
        id = 1702063,
        text = "Yoshino est déjà plus fort qu'avant... \nJo- joyeuse Saint-Valentin~",
        minipack = 0,
    },
    [1702064] = {
        id = 1702064,
        text = "Ara, même s'il a été destiné ainsi, je me sens encore chanceux parfois~\nde te rencontrer dans la rivière du temps.",
        minipack = 0,
    },
    [1702065] = {
        id = 1702065,
        text = "Stupide Grand frère, ce festival est pour les amoureux, mais j'ai des mots à te dire. \nMerci d'être là pour moi tout le temps.",
        minipack = 0,
    },
    [1702066] = {
        id = 1702066,
        text = "Aujourd'hui, je vous tiendrai la main pour marcher sur la plaine fleurie ou sous la forêt aux pétales. \nJusqu'à ce que notre ombre s'allonge dans la lumière du coucher de soleil.",
        minipack = 0,
    },
    [1702067] = {
        id = 1702067,
        text = "En fait, je veux être honnête avec vous parfois...\nMais j'attends le moment parfait.",
        minipack = 0,
    },
