        minipack = 0,
    },
    [1702397] = {
        id = 1702397,
        text = "Maman, il y a un étrange ojisan ici !",
        minipack = 0,
    },
    [1702398] = {
        id = 1702398,
        text = "Tsk, le corps rétréci est vraiment gênant...",
        minipack = 0,
    },
    [1702399] = {
        id = 1702399,
        text = "Je dois aller à la salle de bains. Mais je ne peux pas le faire moi-même.",
        minipack = 0,
    },
    [1702400] = {
        id = 1702400,
        text = "Je veux des cookies. Nourris-moi.",
        minipack = 0,
    },
    [1702401] = {
        id = 1702401,
        text = "Je m'appelle Chiyogami. Heureux de te rencontrer.",
        minipack = 0,
    },
    [1702402] = {
        id = 1702402,
        text = "Je suis le fruit de l'amour de mes parents.",
        minipack = 0,
    },
    [1702403] = {
        id = 1702403,
        text = "Papa, ne fais rien de stupide.",
        minipack = 0,
    },
    [1702404] = {
        id = 1702404,
        text = "Classe 3A",
        minipack = 0,
    },
    [1702405] = {
        id = 1702405,
        text = "Chiyogami Itsuka",
        minipack = 0,
    },
    [1702406] = {
        id = 1702406,
        text = "Même la plus petite maison doit avoir une large entrée pour faire preuve de courtoisie envers les visiteurs. C'est aussi là que \"l'interaction spéciale\" avec les Esprits pourrait se produire !",
        minipack = 0,
    },
    [1702407] = {
        id = 1702407,
