    [1702410] = {
        id = 1702410,
        text = "",
        minipack = 0,
    },
    [1702411] = {
        id = 1702411,
        text = "An average home. This angle is great.",
        minipack = 0,
    },
    [1702412] = {
        id = 1702412,
        text = "",
        minipack = 0,
    },
    [1702413] = {
