    [1702414] = {
        id = 1702414,
        text = "",
        minipack = 0,
    },
    [1702415] = {
        id = 1702415,
        text = "",
        minipack = 0,
    },
    [1702416] = {
        id = 1702416,
        text = "Pendant la construction de cet appartement, Kotori voulait que les Esprits vivent dans un monde rose. Même le fier Kurumi a un côté tendre, n'est-ce pas ? (Bien qu'elle ne vive pas ici à la fin^0^)",
        minipack = 0,
    },
    [1702417] = {
        id = 1702417,
        text = "Pour en savoir plus sur la vie quotidienne d'Esprit, visite plus souvent leur salon. Vous pouvez même bénéficier d'un \"service\" spécial.",
        minipack = 0,
    },
    [1702418] = {
        id = 1702418,
        text = "C'est là que les Esprits dorment la nuit. J'espère que la chambre avec vue nocturne sur la Ville de Tengu leur donnera un rêve romantique.",
        minipack = 0,
    },
    [1702419] = {
        id = 1702419,
        text = "Chaque soir, dans le salon de l'endroit où vivent les esprits, si la télévision est allumée, tu entendras sûrement le cri de Yoshinon et celui de Natsumi. Cela signifie que le drame est en marche.",
        minipack = 0,
    },
    [1702420] = {
        id = 1702420,
        text = "",
        minipack = 0,
    },
    [1702421] = {
        id = 1702421,
        text = "",
        minipack = 0,
    },
    [1702422] = {
        id = 1702422,
        text = "Même la lumière du soleil la plus brillante ne peut chasser la morosité du cœur d'Esprit. Pourquoi un Esprit doit-il s'asseoir et écouter les enseignants ? Quel mal de tête.",
        minipack = 0,
    },
    [1702423] = {
        id = 1702423,
        text = "Les étudiants paresseux se rassemblent parfois sur le toit vide. Certains prétendent avoir vu une fois une mystérieuse jeune fille en rouge avec un beau visage inoubliable.",
        minipack = 0,
    },
    [1702424] = {
        id = 1702424,
        text = "Le couloir peut rappeler aux vilains élèves la punition debout. Il devient plutôt chahuteur entre les cours, oh comme le bon temps passe...",
        minipack = 0,
    },
    [221001] = {
        id = 221001,
        text = "Les données sur les rendez-vous n'existent pas",
        minipack = 0,
    },
    [1702426] = {
        id = 1702426,
        text = "On dit que c'est le meilleur endroit pour admirer la lune. Mais peu viendraient ici la nuit, n'est-ce pas ? Si tu vois l'ombre d'une fille seule, ne sois pas trop surpris.",
        minipack = 0,
    },
    [1702427] = {
        id = 1702427,
        text = "Le couloir est assez nocturne, mais ce n'est pas un bon endroit pour les rencontres. Peut-être que seuls certains esprits aiment ce genre d'endroit.",
        minipack = 0,
    },
