    [1702462] = {
        id = 1702462,
        text = "Fleuriste bien décoré a l'air très classe. Chaque fille aime des fleurs différentes ici. On peut dire que cette simple Boutique de fleurs contient en fait la plus grande connaissance de rendez-vous.",
        minipack = 0,
    },
    [1702463] = {
        id = 1702463,
        text = "Lorsque tu te sent épuisé de rendre les Esprits heureux, viens au magasin de boissons. Une tasse de chocolat glacé rendra les Esprits heureux et vous permettra de refaire le plein d'Endurance.",
        minipack = 0,
    },
    [1702464] = {
        id = 1702464,
        text = "Le Fleuriste est visité par des papillons la nuit pour son parfum. Les fleurs sous la nuit apporteront une expérience de rencontre différente.",
        minipack = 0,
    },
    [221006] = {
