        minipack = 0,
    },
    [1702483] = {
        id = 1702483,
        text = "Un test de courage ? Je ne suis pas intéressée, pas du tout intéressée... JE NE SUIS VRAIMENT PAS INTÉRESSÉE... Ayh !",
