        minipack = 0,
    },
    [1702486] = {
        id = 1702486,
        text = "Savoure un verre de cola glacé dans la source chaude, c'est la meilleure chose que vous puissiez avoir dans la vie ! Ah ! D'où vient cet ojisan ?",
