    [2101084] = {
        id = 2101084,
        text = "Certains livres sont rangés dans le casier. Le premier est Apprendre le C++ de manière impossible, le suivant est... peu importe, tu n'as pas besoin de les lire.",
        minipack = 0,
    },
    [2101086] = {
        id = 2101086,
        text = "Il y a beaucoup de marques [||||] gravées dans le casier, il y a une ligne en dessous : Continue à suivre mes cheveux perdus.",
