    [2101088] = {
        id = 2101088,
        text = "La ventouse est remplie de goji. Et à côté, un stéthoscope ?",
        minipack = 0,
    },
    [2101090] = {
        id = 2101090,
        text = "Il y a une boîte de shampoing dans le casier. Le shampoing bawang... Cela me semble familier.",
        minipack = 0,
    },
    [2101092] = {
        id = 2101092,
        text = "Le sort pour ouvrir le casier est gravé dessus : Une clé qui cache les pouvoirs des ténèbres ! Révèle votre véritable pouvoir devant moi. Je te commande en vertu de notre contrat. Libère le sceau !",
        minipack = 0,
    },
    [2101094] = {
        id = 2101094,
        text = "Note du programmeur : Je vais à Akihabar avec mon stupide waifu Tohka pour la fête du printemps.",
        minipack = 0,
    },
    [2101096] = {
        id = 2101096,
        text = "Parmi les nombreux haltères, il y a un verre de poudre d'albumine et une demi-banane sur le casier.",
        minipack = 0,
    },
    [2101098] = {
        id = 2101098,
        text = "Il y a une paire de pantoufles dedans. Ils sentent... parfumés... pourquoi ! ?",
        minipack = 0,
    },
    [2101100] = {
        id = 2101100,
        text = "Les articles de toilette sont placés de manière ordonnée dans le casier. Il existe même des masques faciaux et des produits de soins de la peau.",
        minipack = 0,
    },
    [2101102] = {
        id = 2101102,
        text = "Elle ressemble à une lettre d'amour telle qu'elle est écrite : Je vais créer 1001 objectifs.",
        minipack = 0,
    },
    [2101104] = {
        id = 2101104,
        text = "L'ancienne cartouche de jeu comporte un homme aux cheveux hérissés, en costume bleu, qui pointe vers quelque chose sur la couverture. Il a l'air plutôt radieux.",
        minipack = 0,
    },
    [2101106] = {
        id = 2101106,
        text = "Il y a une note où il est écrit : Je n'ai rien changé en secret, je n'ai rien changé en secret, je n'ai rien changé en secret...",
        minipack = 0,
    },
    [2101108] = {
        id = 2101108,
        text = "Il y a un modèle de kit d'un homme étrange dans le casier. On y lit : [Je ne veux pas vivre !]",
        minipack = 0,
    },
    [2101110] = {
        id = 2101110,
        text = "Il est écrit sur le carnet de notes : X.X Sunny. Événement : Les joueurs trouvent 5 bugs. Solution : Tue 2 concepteurs de jeux.",
        minipack = 0,
    },
    [2101112] = {
        id = 2101112,
        text = "Une note rose clignotante : Cher programmeur, puis-je ajouter une exigence, juste une... ?",
        minipack = 0,
    },
    [2101114] = {
        id = 2101114,
        text = "Il y a une série complète de light novel Date A Live dans le casier.",
        minipack = 0,
    },
    [2101116] = {
