        text = "Il y a deux tickets de cinéma inutilisés du [2020.9.21]... (Attends, le bêta-test public a été mis en ligne ce jour-là !)",
        minipack = 0,
    },
    [2101118] = {
        id = 2101118,
        text = "Il est rempli de toutes sortes de produits physiques de DAL. Au milieu, il y a une ligne qui dit : \"Espérons que notre jeu s'améliorera de plus en plus !\"",
        minipack = 0,
    },
    [2101120] = {
