        minipack = 0,
    },
    [10503104] = {
        id = 10503104,
        text = "Dans la forme hallebarde, Kotori a 20 % de chances d'allumer les cibles lorsqu'elles sont touchées et augmente les dégâts de compétence de 2550%. \n[Les cibles allumées subissent des DEG égaux à 10 % de l'ATQ de Kotori chaque seconde. Dure 8s. S’empile jusqu'à 10 montants. Au maximum du montant, Kotori allume les cibles avec 1 exploration de flamme supplémentaire, infligeant des DEG égaux à 30 % de l'ATQ de Kotori dans une petite zone. Les dégâts infligés par l'exploration recalculent le DEF des cibles. ]",
        minipack = 0,
    },
    [10503112] = {
