    [13310528] = {
        id = 13310528,
        text = "Chers Partenaires,\n Merci pour votre soutien à Date A Live et Hot Games. Grâce à votre compagnie, les Esprits vont bientôt commencer leur première fête du nouvel an lunaire. \nMerci à tous pour votre soutien sans faille ! Nous nous efforcerons de faire de notre mieux pour améliorer ce jeu !\nLes rencontres ne s'arrêtent jamais ! \n - Hot Games",
        minipack = 0,
    },
    [13310536] = {
        id = 13310536,
        text = "",
        minipack = 0,
    },
    [13310544] = {
        id = 13310544,
        text = "Chers Partenaires, \n grâce à votre soutien, Date A Live : Spirit Pledge fête son 1er anniversaire. Merci pour votre soutien durable. \n Une année remplie d'une intense romance, grâce à votre soutien. \n Une année remplie de batailles intenses, grâce à votre participation. \n Une année remplie de grandes fondations, grâce à votre confiance. \n Nous sommes impatients de tenir notre promesse et de créer d'autres doux souvenirs avec vous. \n En ce 1er anniversaire, nous promettons de continuer à améliorer ce grand jeu et de vous réserver d'autres surprises agréables. \n DAL : Rendez-vous Sans Fin !",
        minipack = 0,
    },
    [13310552] = {
        id = 13310552,
        text = "J'ai dit \"s'il te plaît, viens en rendez-vous avec moi\" à Origami Tobiichi. Comment va-t-elle réagir ?",
        minipack = 0,
    },
    [13310560] = {
        id = 13310560,
        text = "Pourquoi dois-je acheter les costumes de servante ?!... Je suis totalement confus !",
        minipack = 0,
    },
    [13310568] = {
        id = 13310568,
        text = "Je me demandais comment Kotori devenait si puissante jusqu'à ce qu'elle dise \"parce que je dois te protéger, baka...\"",
        minipack = 0,
