    [13400201] = {
        id = 13400201,
        text = "Une jolie fille qui semble venir d'un lycée voisin et qui travaille à temps partiel. Bien qu'inexpérimentée, elle travaille dur et apprend vite.",
        minipack = 0,
    },
    [13400200] = {
        id = 13400200,
        text = "Une femme de ménage aux cheveux bleus, très populaire auprès des clients. Pourtant, elle soupire toujours inconsciemment.",
        minipack = 0,
    },
    [13400199] = {
        id = 13400199,
        text = "Une jolie femme de ménage qui se montre rarement aux clients. Son spectacle de magie quotidien à 20h00 est le point culminant du café.",
        minipack = 0,
    },
    [13400198] = {
        id = 13400198,
        text = "Elle ne parle jamais avec des clients étranges, et quand elle ne bouge pas, elle ressemble à une poupée de porcelaine.",
        minipack = 0,
    },
    [13400197] = {
        id = 13400197,
        text = "Elle n'a aucune idée de son devoir, mais reste très populaire auprès des clients en raison de sa beauté.",
        minipack = 0,
    },
    [13400196] = {
        id = 13400196,
        text = "Une idole bien connue pour sa voix angélique et son aversion intense pour les clients masculins.",
        minipack = 0,
    },
    [13400195] = {
        id = 13400195,
        text = "Une fille diligente, qui excelle à transformer toutes sortes d'ingrédients en une terrible casserole.",
        minipack = 0,
    },
    [13400194] = {
        id = 13400194,
        text = "Une femme de ménage très prudente qui essaie de tout maintenir en place dans le magasin, mais ce n'est qu'un souhait...",
        minipack = 0,
    },
    [13400193] = {
        id = 13400193,
        text = "Le propriétaire intérimaire du café, qui organise le travail des autres femmes de ménage et gère littéralement tout. Mais elle peut aussi se montrer mignonne parfois.",
        minipack = 0,
    },
    [13400192] = {
        id = 13400192,
        text = "Une femme de chambre avec une aura meurtrière. Malgré sa beauté saisissante, on saurait mieux que de l'approcher avec insouciance.",
        minipack = 0,
    },
    [13400191] = {
        id = 13400191,
        text = "Une bonne connue sous le nom de \"gourou des rencontres\". Ses personnalités extraverties font souvent perdre du terrain aux autres.",
        minipack = 0,
    },
    [13400190] = {
        id = 13400190,
        text = "La femme de chambre la plus populaire du café. Les clients pardonnent toujours à cette fauteur de troubles, car elle est bien trop mignonne.",
        minipack = 0,
    },
    [13400189] = {
        id = 13400189,
        text = "Une femme de chambre blonde qui a l'air agressive, mais qui peut devenir perplexe lorsqu'elle est grondée par les clients.",
        minipack = 0,
    },
    [13400188] = {
        id = 13400188,
        text = "Une jolie bonne à lunettes qui se moque toujours des autres, mais si vous osez la provoquer, elle vous jouera des tours par derrière.",
        minipack = 0,
    },
    [13400187] = {
        id = 13400187,
        text = "Une femme de chambre à l'air innocent et aux cheveux courts. Ne faites pas attention à ses remarques incisives occasionnelles.",
        minipack = 0,
    },
    [13400186] = {
        id = 13400186,
        text = "Femme de chambre extravertie avec une queue de cheval, bonne masseuse, sa franchise gêne parfois les clients.",
