    },
    [13400185] = {
        id = 13400185,
        text = "Une femme de chambre mature avec de la fatigue sur le visage. Bien que distraite, elle se rattrape par son attitude et ses manières polies.",
        minipack = 0,
    },
    [13400184] = {
