    [2101085] = {
        id = 2101085,
        text = "Écrit au coin de la laiterie : Je vais donner à ma femme le téléphone portable gagné lors de la fête annuelle de l'entreprise et elle me donne de l'argent. Ka-ching !",
        minipack = 0,
    },
    [2101087] = {
        id = 2101087,
        text = "Il y a une ligne rouge en gras : Quand les designers me demandent de faire quelque chose, ils doivent l'écrire !!!",
        minipack = 0,
    },
    [2101089] = {
