        minipack = 0,
    },
    [2101095] = {
        id = 2101095,
        text = "Le bouillon pratique pour les nuits blanches a un goût aigre et amer. Et il y a une boîte de nouilles de riz aux escargots de rivière à côté...",
        minipack = 0,
