    },
    [2101099] = {
        id = 2101099,
        text = "Dans les casiers sont accrochés tant de chemises unies que les programmeurs aiment. Rouge, vert et bleu... tout ce que vous voulez.",
        minipack = 0,
    },
    [2101101] = {
        id = 2101101,
        text = "Il est rempli d'une boisson fonctionnelle pour les nuits blanches - [Hot Games Cola].",
        minipack = 0,
    },
    [2101103] = {
