        text = "Un bouquet de rose fanée est posé au coin. Peut-être que la Game Designer a oublié de sortir avec sa petite amie à cause d'un surcroît de travail.",
        minipack = 0,
    },
    [2101113] = {
        id = 2101113,
        text = "Le casier est rempli de toutes sortes de lettres d'amour et de roses. (Un Game Designer peut-il être aussi charmant ?)",
        minipack = 0,
    },
    [2101115] = {
        id = 2101115,
        text = "Dépliez le joli coussin en forme de radis et vous obtiendrez un tapis. (Quelqu'un dort dans le bureau ?)",
        minipack = 0,
    },
    [2101117] = {
