    },
    [13310540] = {
        id = 13310540,
        text = "Chers Partenaires, \n grâce à la dernière technologie fournie par Natsumi, l'IA chat de Tohka - \"Tohbaka\" - a officiellement rejoint Ratatoskr. \nNous avons travaillé dur pour améliorer le jeu et ajouter plus de contenus de meilleure qualité. D'autres esprits se joindront au chat plus tard. Nous vous attendons avec impatience !\n Hot Games",
        minipack = 0,
