    },
    [32317] = {
        id = 32317,
        text = "",
        minipack = 0,
    },
    [13310533] = {
        id = 13310533,
        text = "Chers Partenaires, \n après des mois d'entraînement, Shekhinah Tohka est maintenant beaucoup plus puissante. L'effet \"Pénétration\" a également été renforcé. \n Nous avons tenu nos promesses. Rassurez-vous, le jeu va s'améliorer et votre waifu deviendra plus fort (avec un plus gros appétit). \n Un concepteur sous le pseudonyme de D-A-L",
        minipack = 0,
    },
    [13310532] = {
        id = 13310532,
        text = "Chers Partenaires, \n Dans la dernière mise à jour, nous avons modifié l'effet de \"Pénétration\" et Tohka Améliorée en fonction de la demande populaire. \nNous vous prions de croire que nous tiendrons nos promesses à la fin. Nous avons travaillé dur pour améliorer ce jeu et aider la marque. Comme toujours, faites-nous connaître nos lacunes et aidez-nous à nous améliorer. \n - Digne Hot Games",
        minipack = 0,
    },
    [1706042] = {
        id = 1706042,
        text = "Initialisation du programme - bee bo beebo～～",
        minipack = 0,
    },
    [13310529] = {
        id = 13310529,
        text = "Chers Partenaires, \n grâce à votre compagnie, les Esprits vont bientôt commencer leur premier festival du nouvel an lunaire. \n Merci à tous de nous aider à grandir et à devenir meilleurs ! Nous apprécions vraiment votre soutien et votre tolérance !\n Les rencontres ne s'arrêtent jamais ! Je vous aime tous !\n - Designer Sima",
        minipack = 0,
    },
    [42106] = {
        id = 42106,
        text = "Gemme d'Énergie Classe SS, obtenez une Gemme de Classe SS pour une compétence aléatoire de [Ellen]. (Auto utilisé une fois obtenue)",
        minipack = 0,
    },
    [13310527] = {
