    [2108027] = {
        id = 2108027,
        text = "Alors que des ennemis inattendus s'avancent, Mayuri se joint à eux pour combattre. Étant donné que tout est nouveau dans ce monde, comment Mayuri verra-t-elle ce côté de l'humanité ?",
        minipack = 0,
    },
    [2108029] = {
